script.text:
			
function init$&Identity;Filter$(f) { 
	var g = f.grid, v = f._language == 'v', id = g.get_id(), row = g._activeRow;
	var l0 = g._getColumnOrder('stt_rec'), l1 = g._getColumnOrder('so_ct'), l2 = g._getColumnOrder('ngay_ct'), l3 = g._getColumnOrder('ngay_hs_tt');
	f.setItemValues('stt_rec, so_ct, ngay_ct, ngay_hs_tt', [g._getItemValue(row, l0), $func.trim(g._getItemValue(row, l1)), g._getItemValue(row, l2),  g._getItemValue(row, l3)]);

}
function active$&Identity;Filter$(f) {	
	f.add_commandEvent(on$&Identity;$ExecuteCommand);
}
function close$&Identity;Filter$(f) {
	try {f.remove_commandEvent(on$&Identity;$ExecuteCommand);} catch (ex) {}
	
}
 
function on$&Identity;$ExecuteCommand(sender, e) {
	var action = e.type.Action, f = sender, g = f.grid;
	switch (action) { 
		case 'Gather': 
			e.type.cancelEvent = true;
			
			updateNgayHSTT(g, g._activeRow, f.getItemValue('ngay_hs_tt'));	
			f.closeDialog();
	
			
			break; 
		default:
			break;
	}
}
